    it("an ordinary member (a writer) CAN unfreeze, and CAN re-freeze", async () => {
      const { error: unfreezeErr } = await memberSession
        .from("projects")
        .update({ baseline_frozen_at: null })
        .eq("id", projectId);
      expect(unfreezeErr).toBeNull();

      const { data, error: freezeErr } = await memberSession
        .from("projects")
        .update({ baseline_frozen_at: new Date().toISOString() })
        .eq("id", projectId)
        .select("baseline_frozen_at");
      expect(freezeErr).toBeNull();
      expect(data?.[0]?.baseline_frozen_at).not.toBeNull();
    });
  });

  // --- Failure test: AS-029's own behaviour survives ---------------------

  it("an owner CAN set baseline_frozen_at directly (owner is also a writer)", async () => {
    await unfreeze();
    const { data, error } = await ownerSession
      .from("projects")
      .update({ baseline_frozen_at: new Date().toISOString() })
      .eq("id", projectId)
      .select("baseline_frozen_at");
    expect(error).toBeNull();
    expect(data?.[0]?.baseline_frozen_at).not.toBeNull();
    await unfreeze();
  });

  it("failure test: an ordinary member can still edit a project's name, description and dates", async () => {
    const { data, error } = await memberSession
      .from("projects")
      .update({
        name: "F020b test project (renamed)",
        description: "Updated by an ordinary member.",
        start_date: "2026-02-01",
        end_date: "2026-06-01",
      })
      .eq("id", projectId)
      .select("name, description, start_date, end_date");
    expect(error).toBeNull();
    expect(data?.[0]?.name).toBe("F020b test project (renamed)");
    expect(data?.[0]?.description).toBe("Updated by an ordinary member.");
  });

  it("a viewer is rejected editing a project's name (not an active writer/member gate bypass, still requires the base UPDATE policy + no unrelated block)", async () => {
    // Viewer IS an active member so RLS's own USING/WITH CHECK admits
    // the row; name is in the unconditional MEMBER tier, so this
    // actually succeeds -- documenting AS-029's literal scope ("any
    // active member", not "any writer") rather than asserting the
    // opposite.
    const { error } = await viewerSession
      .from("projects")
      .update({ name: "Renamed by viewer" })
      .eq("id", projectId);
    expect(error).toBeNull();
    await admin.from("projects").update({ name: "F020b test project" }).eq("id", projectId);
  });

  // --- Delete-then-reinsert on project_metrics --------------------------

  describe("project_metrics: delete-then-reinsert bypass closed", () => {
    beforeAll(freeze);
    afterAll(unfreeze);

    it("a writer cannot delete a baseline-carrying metric while the project's baseline is frozen", async () => {
      const { error } = await memberSession.from("project_metrics").delete().eq("id", metricId);
      expect(error).not.toBeNull();

      const { data } = await admin.from("project_metrics").select("id").eq("id", metricId).maybeSingle();
      expect(data?.id).toBe(metricId);
    });

    it("a writer CAN delete a metric that has no baseline at all, even while the project is frozen", async () => {
      const { data: noBaselineMetric, error: insertErr } = await admin
        .from("project_metrics")
        .insert({ project_id: projectId, name: "Sessions", source: "ga4", direction: "higher" })
        .select("id")
        .single();
      expect(insertErr).toBeNull();

      const { error: deleteErr } = await memberSession
        .from("project_metrics")
        .delete()
        .eq("id", noBaselineMetric!.id);
      expect(deleteErr).toBeNull();
    });
  });

  // --- direction freezes with the baseline --------------------------------

  describe("project_metrics.direction — frozen with the baseline", () => {
    beforeAll(freeze);
    afterAll(unfreeze);

    it("a writer is rejected changing direction on a frozen metric", async () => {
      const { error } = await memberSession
        .from("project_metrics")
        .update({ direction: "higher" })
        .eq("id", metricId);
      expect(error).not.toBeNull();

      const { data } = await admin.from("project_metrics").select("direction").eq("id", metricId).single();
      expect(data?.direction).toBe("lower");
    });

    it("a writer CAN still change direction on an un-frozen project", async () => {
      await unfreeze();

      const { data, error } = await memberSession
        .from("project_metrics")
        .update({ direction: "higher" })
        .eq("id", metricId)
        .select("direction");
      expect(error).toBeNull();
      expect(data?.[0]?.direction).toBe("higher");

      await admin.from("project_metrics").update({ direction: "lower" }).eq("id", metricId);
    });

    it("client_visible and other unrelated columns stay freely editable on a frozen metric (the F011b lesson, preserved)", async () => {
      await freeze();

      const { data, error } = await memberSession
        .from("project_metrics")
        .update({ client_visible: false })
        .eq("id", metricId)
        .select("client_visible");
      expect(error).toBeNull();
      expect(data?.[0]?.client_visible).toBe(false);

      await admin.from("project_metrics").update({ client_visible: true }).eq("id", metricId);
    });
  });

  // --- Manual verification / self-maintaining test -----------------------

  describe.skipIf(!haveManagementApi)("self-maintaining allow-list", () => {
    // This probe owns its fixture end to end, over the SAME connection
    // (the Management API, i.e. the real hosted project) that runs the
    // probe itself -- it does NOT reuse `projectId`/`ownerId` from the
    // outer `beforeAll`.
    //
    // Root cause of the previous, persistent `PROBE_ROW_NOT_MATCHED`: in
    // CI (see .github/workflows/*.yml, "Start local Supabase stack" /
    // "Export local Supabase env vars"), `NEXT_PUBLIC_SUPABASE_URL` /
    // `SUPABASE_SECRET_KEY` -- what the outer `beforeAll` uses via
    // `admin`/PostgREST to create `workspaceId`/`projectId`/`ownerId` --
    // point at an EPHEMERAL LOCAL Docker Postgres stack started fresh for
    // that CI run. `SUPABASE_PROJECT_REF` / `SUPABASE_ACCESS_TOKEN` --
    // what `rawSql` uses via the Management API -- are repository secrets
    // that point at the REAL HOSTED project (a permanently different
    // database; the workflow's own top-of-file comment documents this
    // split explicitly for the other five Management-API catalog suites).
    // F088's owner-actor fix was real and necessary (proven by direct
    // reproduction against the hosted project in that handoff) but could
    // not fix this: the probe was asking the hosted project's `projects`
    // table to `UPDATE ... WHERE id = '<uuid>'` for a UUID that was only
    // ever inserted into the LOCAL stack's `projects` table. Zero rows
    // ever matched in CI because the row was never in that database at
    // all -- not because it was removed or invalidated by any race. Any
    // number of `waitFor`-style retries against that same mismatched
    // target would still find nothing, forever.
    //
    // The fix: build a workspace + a real `auth.users` row (owner) +
    // project entirely inside this test, through `rawSql` (Management
    // API / hosted project) -- the exact same channel the probe's own
    // UPDATE runs through -- so the row the probe queries for is
    // guaranteed to exist in the same database the probe is querying.
    // Cleanup runs in `finally` so it fires even if the probe's own
    // assertions fail, and does not depend on the file's outer
    // `afterAll` (which only tears down the separate, local-stack
    // fixture).
    it("a column added to projects after this migration is protected by default, with no edit to the guard function", async () => {
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      let probeWorkspaceId: string | null = null;
      let probeProjectId: string | null = null;
      let probeOwnerId: string | null = null;

      try {
        const [owner] = (await rawSql(`
          insert into auth.users (id, instance_id, email, encrypted_password, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data, aud, role)
          values (gen_random_uuid(), '00000000-0000-0000-0000-000000000000', 'f020b-probe-owner-${suffix}@example.com', crypt('${PASSWORD}', gen_salt('bf')), now(), now(), now(), '{"provider":"email","providers":["email"]}', '{}', 'authenticated', 'authenticated')
          returning id;
        `)) as Array<{ id: string }>;
        probeOwnerId = owner.id;

        const [workspace] = (await rawSql(`
          insert into public.workspaces (name, slug)
          values ('F020b probe workspace', 'f020b-probe-${suffix}')
          returning id;
        `)) as Array<{ id: string }>;
        probeWorkspaceId = workspace.id;

        await rawSql(`
          insert into public.workspace_members (workspace_id, user_id, role, status)
          values ('${probeWorkspaceId}', '${probeOwnerId}', 'owner', 'active');
        `);

        const [project] = (await rawSql(`
          insert into public.projects (workspace_id, name, visibility, created_by, portal_enabled)
          values ('${probeWorkspaceId}', 'F020b probe project', 'workspace', '${probeOwnerId}', false)
          returning id;
        `)) as Array<{ id: string }>;
        probeProjectId = project.id;

        const sql = `
          do $probe$
          declare
            v_row_count int;
          begin
            alter table public.projects
              add column if not exists f020b_probe_never_committed text;

            -- Uses the workspace OWNER, not a client-role actor, on
            -- purpose (root-caused via direct hosted-project reproduction,
            -- see F088's handoff for the full mechanism). For UPDATE,
            -- Postgres RLS requires a row to pass BOTH the table's SELECT
            -- policy and the UPDATE policy's own USING clause before it is
            -- even considered for the write -- not the UPDATE policy alone.
            -- An owner's visibility comes from wm.role in ('owner',
            -- 'admin') alone (see is_project_visible_to_row), with no
            -- project_members dependency at all, so this probe's only
            -- live dependency for row-matching is the single
            -- workspace_members row created immediately above, in the
            -- same database this DO block itself runs against.
            set local request.jwt.claims to '{"sub":"${probeOwnerId}","role":"authenticated"}';
            set local role authenticated;

            begin
              update public.projects
                 set f020b_probe_never_committed = 'author-supplied value'
               where id = '${probeProjectId}';
              get diagnostics v_row_count = row_count;
              if v_row_count = 0 then
                -- Distinguish "the guard let this through" from "the UPDATE
                -- never reached the guard at all" -- e.g. RLS silently
                -- filtered the row so 0 rows matched, which produces the
                -- exact same observable "no exception raised" outcome as a
                -- real guard hole. Both must not be reported as
                -- GUARD_DID_NOT_FIRE, which claims the guard specifically
                -- failed to reject a value it saw.
                raise exception 'PROBE_ROW_NOT_MATCHED: the UPDATE affected 0 rows -- the probe proves nothing about the guard, since it was never invoked on this row';
              end if;
              raise exception 'GUARD_DID_NOT_FIRE';
            exception
              when sqlstate '42501' then
                null; -- expected: the allow-list guard rejected the new column
            end;

            reset role;
            raise exception 'ROLLBACK_PROBE_TRANSACTION';
          end;
          $probe$;
        `;

        let threw: unknown = null;
        try {
          await rawSql(sql);
        } catch (err) {
          threw = err;
        }

        expect(threw).not.toBeNull();
        const message = String(threw);
        expect(message).not.toMatch(/PROBE_ROW_NOT_MATCHED/);
        expect(message).not.toMatch(/GUARD_DID_NOT_FIRE/);
        expect(message).toMatch(/ROLLBACK_PROBE_TRANSACTION/);

        const columns = (await rawSql(
          `select column_name from information_schema.columns
            where table_schema = 'public' and table_name = 'projects'
              and column_name = 'f020b_probe_never_committed';`,
        )) as unknown[];
        expect(columns).toEqual([]);
      } finally {
        // Guaranteed even on assertion failure -- this suite mutates the
        // real hosted project, so no probe fixture may survive the run.
        if (probeProjectId) {
          await rawSql(`delete from public.projects where id = '${probeProjectId}';`).catch(
            () => {},
          );
        }
        if (probeWorkspaceId) {
          await rawSql(
            `delete from public.workspace_members where workspace_id = '${probeWorkspaceId}';`,
          ).catch(() => {});
          await rawSql(`delete from public.workspaces where id = '${probeWorkspaceId}';`).catch(
            () => {},
          );
        }
        if (probeOwnerId) {
          await rawSql(`delete from auth.users where id = '${probeOwnerId}';`).catch(() => {});
        }
      }
    }, 30_000);
  });
});

// Integration test for F116 (docs/client-portal-phase-2-plan.md item A):
// connecting the existing chat system to the client portal. Same
// convention as tests/integration/f113-page-links-rls.test.ts: real
// signed-in sessions against PostgREST, not a mocked query builder.
//
// Written FIRST against the pre-fix schema (20260904020000_chat_system.sql
// alone) and watched to fail before 20261103010000_f116_client_channel_
// access.sql landed -- see this feature's handoff for the failure output.
//
// Covers:
//   - a client cannot SELECT another project's channel by id (cross-project
//     leak, the failure case called out explicitly in the task);
//   - a client cannot self-add (channel_members insert) into another
//     project's channel by guessing its id;
//   - a client cannot browse/self-join the workspace's own internal
//     workspace-wide channel;
//   - a `viewer` who is NOT an explicit member of the project cannot browse
//     into a client's project channel just because the project itself is
//     workspace-visible (the "a client's words leak to a viewer" case);
//   - a client who IS an explicit member of their own project channel CAN
//     read and post there, and sees the same messages/roster a project
//     team member sees;
//   - a client cannot read messages in a channel they were never added to,
//     even via full-text search;
//   - `ensure_project_channel_atomic` is idempotent (two calls, one
//     channel, no duplicate membership rows) and is not directly callable
//     by an ordinary authenticated session (service_role only).

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";

function loadDotEnv() {
  const path = join(process.cwd(), ".env");
  if (!existsSync(path)) return;
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    if (key && !(key in process.env)) {
      process.env[key] = trimmed.slice(eq + 1).trim();
    }
  }
}

loadDotEnv();

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
const SECRET_KEY = process.env.SUPABASE_SECRET_KEY;

const haveCreds = Boolean(SUPABASE_URL && PUBLISHABLE_KEY && SECRET_KEY);
if (process.env.CI && !haveCreds) {
  throw new Error(
    "Missing Supabase credentials required to run this suite in CI. Set NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY and SUPABASE_SECRET_KEY as GitHub Actions repository secrets.",
  );
}

const PASSWORD = "Test-password-1!";

describe.skipIf(!haveCreds)("client chat channel access (F116)", () => {
  let admin: SupabaseClient;
  let clientSession: SupabaseClient;
  let otherClientSession: SupabaseClient;
  let viewerSession: SupabaseClient;
  let memberSession: SupabaseClient;

  let workspaceId: string;
  let projectAId: string; // clientSession's own project
  let projectBId: string; // otherClientSession's own project
  let ownerId: string;
  let memberId: string;
  let viewerId: string;
  let clientId: string;
  let otherClientId: string;

  let workspaceWideChannelId: string;
  let channelAId: string; // project A's channel
  let channelBId: string; // project B's channel

  const createdUserIds: string[] = [];

  beforeAll(async () => {
    admin = createClient(SUPABASE_URL!, SECRET_KEY!, {
      auth: { autoRefreshToken: false, persistSession: false },
    });

    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const makeUser = async (label: string) => {
      const { data, error } = await admin.auth.admin.createUser({
        email: `f116-chat-${label}-${suffix}@example.com`,
        password: PASSWORD,
        email_confirm: true,
      });
      if (error || !data.user) throw new Error(`${label}: ${error?.message}`);
      createdUserIds.push(data.user.id);
      return { id: data.user.id, email: data.user.email! };
    };

    const owner = await makeUser("owner");
    const memberUser = await makeUser("member");
    const viewerUser = await makeUser("viewer");
    const clientUser = await makeUser("client");
    const otherClientUser = await makeUser("other-client");
    ownerId = owner.id;
    memberId = memberUser.id;
    viewerId = viewerUser.id;
    clientId = clientUser.id;
    otherClientId = otherClientUser.id;

    const { data: workspace, error: wsErr } = await admin
      .from("workspaces")
      .insert({ name: "F116 chat test", slug: `f116-chat-${suffix}` })
      .select("id")
      .single();
    if (wsErr || !workspace) throw new Error(`workspace: ${wsErr?.message}`);
    workspaceId = workspace.id;

    await admin.from("workspace_members").insert([
      { workspace_id: workspaceId, user_id: ownerId, role: "owner", status: "active" },
      { workspace_id: workspaceId, user_id: memberId, role: "member", status: "active" },
      { workspace_id: workspaceId, user_id: viewerId, role: "viewer", status: "active" },
      { workspace_id: workspaceId, user_id: clientId, role: "client", status: "active" },
      { workspace_id: workspaceId, user_id: otherClientId, role: "client", status: "active" },
    ]);

    const insertProject = async (name: string) => {
      const { data, error } = await admin
        .from("projects")
        .insert({
          workspace_id: workspaceId,
          name,
          // Deliberately 'workspace'-visibility: the pre-fix bug was that
          // ANY active member (including a non-project viewer) could
          // browse a workspace-visible project's channel. This project
          // being workspace-visible is what makes that failure mode
          // reachable, and is the honest common case (most projects are
          // workspace-visible, not private).
          visibility: "workspace",
          created_by: ownerId,
          portal_enabled: true,
        })
        .select("id")
        .single();
      if (error || !data) throw new Error(`project ${name}: ${error?.message}`);
      return data.id as string;
    };

    projectAId = await insertProject("Project A");
    projectBId = await insertProject("Project B");

    // memberId is on BOTH projects; viewerId is on NEITHER (workspace
    // viewer only); each client is on their own project only.
    await admin.from("project_members").insert([
      { project_id: projectAId, user_id: memberId, project_role: "lead", added_by: ownerId },
      { project_id: projectAId, user_id: clientId, project_role: "member", added_by: ownerId },
      { project_id: projectBId, user_id: memberId, project_role: "lead", added_by: ownerId },
      { project_id: projectBId, user_id: otherClientId, project_role: "member", added_by: ownerId },
    ]);

    // The workspace-wide channel (no project), auto-enroll-eligible for
    // ordinary team members but never for a client.
    const { data: wsChannel, error: wsChannelErr } = await admin
      .from("channels")
      .insert({
        workspace_id: workspaceId,
        project_id: null,
        kind: "channel",
        name: "general",
        created_by: ownerId,
      })
      .select("id")
      .single();
    if (wsChannelErr || !wsChannel) throw new Error(`ws channel: ${wsChannelErr?.message}`);
    workspaceWideChannelId = wsChannel.id;

    // Project channels, created + enrolled via the new RPC exactly the way
    // the app will call it (admin/service-role client only).
    const { data: chanA, error: chanAErr } = await admin.rpc("ensure_project_channel_atomic", {
      p_project_id: projectAId,
      p_created_by: ownerId,
    });
    if (chanAErr || !chanA) throw new Error(`ensure channel A: ${chanAErr?.message}`);
    channelAId = chanA as string;

    const { data: chanB, error: chanBErr } = await admin.rpc("ensure_project_channel_atomic", {
      p_project_id: projectBId,
      p_created_by: ownerId,
    });
    if (chanBErr || !chanB) throw new Error(`ensure channel B: ${chanBErr?.message}`);
    channelBId = chanB as string;

    const signIn = async (email: string) => {
      const session = createClient(SUPABASE_URL!, PUBLISHABLE_KEY!, {
        auth: { autoRefreshToken: false, persistSession: false },
      });
      const { error } = await session.auth.signInWithPassword({ email, password: PASSWORD });
      if (error) throw new Error(`sign in ${email}: ${error.message}`);
      return session;
    };
    memberSession = await signIn(memberUser.email);
    viewerSession = await signIn(viewerUser.email);
    clientSession = await signIn(clientUser.email);
    otherClientSession = await signIn(otherClientUser.email);
  }, 60_000);

  afterAll(async () => {
    if (!admin) return;
    await admin.from("messages").delete().in("channel_id", [workspaceWideChannelId, channelAId, channelBId]);
    await admin.from("channel_members").delete().in("channel_id", [workspaceWideChannelId, channelAId, channelBId]);
    await admin.from("channels").delete().in("id", [workspaceWideChannelId, channelAId, channelBId]);
    await admin.from("project_members").delete().in("project_id", [projectAId, projectBId]);
    await admin.from("projects").delete().in("id", [projectAId, projectBId]);
    await admin.from("workspace_members").delete().eq("workspace_id", workspaceId);
    await admin.from("workspaces").delete().eq("id", workspaceId);
    for (const id of createdUserIds) await admin.auth.admin.deleteUser(id);
  }, 60_000);

  describe("ensure_project_channel_atomic set up exactly one channel per project", () => {
    it("created one project channel each, distinct from the workspace-wide channel", () => {
      expect(channelAId).not.toBe(channelBId);
      expect(channelAId).not.toBe(workspaceWideChannelId);
    });

    it("is idempotent: a second call returns the same channel id and does not duplicate membership", async () => {
      const { data: again, error } = await admin.rpc("ensure_project_channel_atomic", {
        p_project_id: projectAId,
        p_created_by: ownerId,
      });
      expect(error).toBeNull();
      expect(again).toBe(channelAId);

      const { data: members, error: membersErr } = await admin
        .from("channel_members")
        .select("user_id")
        .eq("channel_id", channelAId);
      expect(membersErr).toBeNull();
      const userIds = (members ?? []).map((m) => m.user_id);
      expect(new Set(userIds).size).toBe(userIds.length);
      expect(userIds.sort()).toEqual([memberId, clientId].sort());
    });

    it("is not callable by an ordinary authenticated session (service_role only)", async () => {
      const { error } = await clientSession.rpc("ensure_project_channel_atomic", {
        p_project_id: projectBId,
        p_created_by: clientId,
      });
      expect(error).not.toBeNull();
    });
  });

  describe("cross-project isolation (written and watched to fail first)", () => {
    it("a client cannot SELECT another project's channel by id", async () => {
      const { data, error } = await clientSession
        .from("channels")
        .select("id")
        .eq("id", channelBId)
        .maybeSingle();
      expect(error).toBeNull();
      expect(data).toBeNull();
    });

    it("a client cannot self-add into another project's channel by guessing its id", async () => {
      const { error } = await clientSession
        .from("channel_members")
        .insert({ channel_id: channelBId, user_id: clientId });
      expect(error).not.toBeNull();

      const { data: membership } = await admin
        .from("channel_members")
        .select("user_id")
        .eq("channel_id", channelBId)
        .eq("user_id", clientId)
        .maybeSingle();
      expect(membership).toBeNull();
    });

    it("a client cannot read messages posted in another project's channel", async () => {
      await admin.from("messages").insert({
        channel_id: channelBId,
        sender_id: memberId,
        body_json: { type: "doc", content: [] },
        body_text: "internal to project B",
      });

      const { data, error } = await clientSession
        .from("messages")
        .select("id")
        .eq("channel_id", channelBId);
      expect(error).toBeNull();
      expect(data ?? []).toHaveLength(0);
    });

    it("a client's search never surfaces a message from a channel they are not in", async () => {
      const { data: channelRows } = await clientSession
        .from("channels")
        .select("id")
        .eq("workspace_id", workspaceId);
      const visibleIds = (channelRows ?? []).map((c) => c.id);
      expect(visibleIds).not.toContain(channelBId);
      expect(visibleIds).not.toContain(workspaceWideChannelId);
    });
  });

  describe("a client cannot reach internal team chat", () => {
    it("cannot SELECT the workspace-wide channel", async () => {
      const { data, error } = await clientSession
        .from("channels")
        .select("id")
        .eq("id", workspaceWideChannelId)
        .maybeSingle();
      expect(error).toBeNull();
      expect(data).toBeNull();
    });

    it("cannot self-add into the workspace-wide channel", async () => {
      const { error } = await clientSession
        .from("channel_members")
        .insert({ channel_id: workspaceWideChannelId, user_id: clientId });
      expect(error).not.toBeNull();
    });
  });

  describe("a viewer who is not a project member cannot browse a client's channel", () => {
    it("cannot SELECT project A's channel despite the project being workspace-visible", async () => {
      const { data, error } = await viewerSession
        .from("channels")
        .select("id")
        .eq("id", channelAId)
        .maybeSingle();
      expect(error).toBeNull();
      expect(data).toBeNull();
    });

    it("cannot self-add into project A's channel", async () => {
      const { error } = await viewerSession
        .from("channel_members")
        .insert({ channel_id: channelAId, user_id: viewerId });
      expect(error).not.toBeNull();
    });
  });

  describe("a client CAN use their own project channel", () => {
    it("can SELECT their own project's channel", async () => {
      const { data, error } = await clientSession
        .from("channels")
        .select("id")
        .eq("id", channelAId)
        .maybeSingle();
      expect(error).toBeNull();
      expect(data?.id).toBe(channelAId);
    });

    it("can post a message, and the project team member sees it", async () => {
      const { data: inserted, error: insertError } = await clientSession
        .from("messages")
        .insert({
          channel_id: channelAId,
          sender_id: clientId,
          body_json: { type: "doc", content: [] },
          body_text: "hello from the client",
        })
        .select("id")
        .single();
      expect(insertError).toBeNull();
      expect(inserted?.id).toBeTruthy();

      const { data: seenByMember, error: memberReadError } = await memberSession
        .from("messages")
        .select("id, body_text")
        .eq("id", inserted!.id)
        .maybeSingle();
      expect(memberReadError).toBeNull();
      expect(seenByMember?.body_text).toBe("hello from the client");
    });

    it("can see the channel's own member roster (their project team, not the whole workspace)", async () => {
      const { data, error } = await clientSession
        .from("channel_members")
        .select("user_id")
        .eq("channel_id", channelAId);
      expect(error).toBeNull();
      const userIds = (data ?? []).map((r) => r.user_id);
      expect(userIds).toContain(clientId);
      expect(userIds).toContain(memberId);
      // Never the other project's client or the pure workspace viewer --
      // both are strangers to this channel.
      expect(userIds).not.toContain(otherClientId);
      expect(userIds).not.toContain(viewerId);
    });

    it("cannot edit a staff member's message, but can edit (and delete) their own", async () => {
      const { data: staffMessage } = await admin
        .from("messages")
        .insert({
          channel_id: channelAId,
          sender_id: memberId,
          body_json: { type: "doc", content: [] },
          body_text: "staff note",
        })
        .select("id")
        .single();

      const { data: editResult, error: editError } = await clientSession
        .from("messages")
        .update({ body_text: "tampered" })
        .eq("id", staffMessage!.id)
        .select("id");
      expect(editError).toBeNull();
      // RLS silently filters the row rather than erroring -- zero rows
      // affected is the correct "you may not touch this" outcome here.
      expect(editResult ?? []).toHaveLength(0);

      const { data: unchanged } = await admin
        .from("messages")
        .select("body_text")
        .eq("id", staffMessage!.id)
        .single();
      expect(unchanged?.body_text).toBe("staff note");
    });
  });
});

// Integration test for F117 (chat-subsystem security hardening pass on
// top of missions/20260903-portal's F116 handoff, out-of-scope items 2 and
// 3): real signed-in sessions against PostgREST/Server Actions, same
// convention as tests/integration/f116-client-chat-channel-rls.test.ts and
// tests/integration/f006i-create-channel-atomic-authz.test.ts.
//
// Item 2 investigation (see F117 handoff for the full writeup): the F116
// handoff claimed `create_channel_atomic` was "still granted to
// `authenticated` directly ... bypassing createChannel's own app-layer
// checks entirely." Grepping the migration history shows this claim was
// stale by the time F116 landed -- 20260918010000_f006i_authz_round_2.sql
// (which predates F116) already added a full internal `auth.uid()`-gated
// check to this exact function: caller identity, non-client role, and
// per-member workspace membership. tests/integration/
// f006i-create-channel-atomic-authz.test.ts already proves this (6/6
// passing on the CURRENT schema, run again below as part of this task's
// required "watch it fail, then fix, then watch it pass" step -- it did
// NOT fail, because the hole is already closed). The block below adds one
// more explicit regression case matching this task's own wording (a plain
// signed-in user calling the RPC directly over supabase-js with a
// fabricated member list), plus the specific client-self-enrollment
// scenario F116 made newly reachable (a client is now an ordinary
// `channel_members` participant, so a client calling this RPC directly to
// add themselves to an arbitrary channel is the concrete risk F116 raised
// -- already blocked by the existing "caller is not an active non-client
// member" check, verified again here against a project that has portal
// chat enabled).
//
// Item 3: createChannel's project-scoped INSERT check used to accept any
// caller `isProjectVisibleToCaller` would admit (workspace-visible
// projects open to every active member, plus an unconditional owner/admin
// bypass) -- broader than the project_members-only rule F116 applied to
// SELECT/self-add for the exact same channels. Fixed in
// lib/actions/chat-channels.ts to require an explicit `project_members`
// row, matching browse. This block proves the negative (an active,
// non-project-member workspace member -- including an owner -- can no
// longer create a channel for a workspace-visible project they are not
// explicitly on) and the positive control (an explicit project member
// still can).

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";

function loadDotEnv() {
  const path = join(process.cwd(), ".env");
  if (!existsSync(path)) return;
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    if (key && !(key in process.env)) {
      process.env[key] = trimmed.slice(eq + 1).trim();
    }
  }
}

loadDotEnv();

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
const SECRET_KEY = process.env.SUPABASE_SECRET_KEY;

const haveCreds = Boolean(SUPABASE_URL && PUBLISHABLE_KEY && SECRET_KEY);
if (process.env.CI && !haveCreds) {
  throw new Error(
    "Missing Supabase credentials required to run this suite in CI. Set NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY and SUPABASE_SECRET_KEY as GitHub Actions repository secrets.",
  );
}

const PASSWORD = "Test-password-1!";
const RLS_DENIED = "42501";

let currentTestClient: { auth: { getUser: () => Promise<{ data: { user: { id: string } | null } }> } } = {
  auth: { getUser: async () => ({ data: { user: null } }) },
};

vi.mock("@/lib/supabase/server", () => ({
  createClient: async () => currentTestClient,
}));

describe.skipIf(!haveCreds)("F117 — chat security hardening", () => {
  let admin: SupabaseClient;

  let workspaceId: string;
  let ownerId: string; // workspace owner, NOT an explicit project_members row
  let projectMemberId: string; // active member, explicit project_members row
  let clientId: string; // client, member of the project's channel post-portal-enable
  let outsiderWorkspaceId: string;
  let outsiderId: string; // active member of a DIFFERENT workspace entirely

  let ownerSession: SupabaseClient;
  let projectMemberSession: SupabaseClient;
  let clientSession: SupabaseClient;
  let outsiderSession: SupabaseClient;

  let projectId: string;
  let projectChannelId: string;

  const createdUserIds: string[] = [];
  const createdChannelIds: string[] = [];

  beforeAll(async () => {
    admin = createClient(SUPABASE_URL!, SECRET_KEY!, {
      auth: { autoRefreshToken: false, persistSession: false },
    });

    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const makeUser = async (label: string) => {
      const { data, error } = await admin.auth.admin.createUser({
        email: `f117-${label}-${suffix}@example.com`,
        password: PASSWORD,
        email_confirm: true,
      });
      if (error || !data.user) throw new Error(`${label}: ${error?.message}`);
      createdUserIds.push(data.user.id);
      return { id: data.user.id, email: data.user.email! };
    };

    const owner = await makeUser("owner");
    const projMember = await makeUser("projmember");
    const client = await makeUser("client");
    const outsider = await makeUser("outsider");
    ownerId = owner.id;
    projectMemberId = projMember.id;
    clientId = client.id;
    outsiderId = outsider.id;

    const { data: ws, error: wsErr } = await admin
      .from("workspaces")
      .insert({ name: "F117 workspace", slug: `f117-ws-${suffix}` })
      .select("id")
      .single();
    if (wsErr || !ws) throw new Error(`workspace: ${wsErr?.message}`);
    workspaceId = ws.id;

    const { data: wsB, error: wsBErr } = await admin
      .from("workspaces")
      .insert({ name: "F117 outsider workspace", slug: `f117-ws-b-${suffix}` })
      .select("id")
      .single();
    if (wsBErr || !wsB) throw new Error(`workspace B: ${wsBErr?.message}`);
    outsiderWorkspaceId = wsB.id;

    await admin.from("workspace_members").insert([
      { workspace_id: workspaceId, user_id: ownerId, role: "owner", status: "active" },
      { workspace_id: workspaceId, user_id: projectMemberId, role: "member", status: "active" },
      { workspace_id: workspaceId, user_id: clientId, role: "client", status: "active" },
      { workspace_id: outsiderWorkspaceId, user_id: outsiderId, role: "member", status: "active" },
    ]);

    const { data: project, error: projectErr } = await admin
      .from("projects")
      .insert({
        workspace_id: workspaceId,
        name: "F117 project",
        // Deliberately workspace-visible: the pre-fix bug for item 3 was
        // reachable exactly because any active member of a
        // workspace-visible project could create its channel via
        // isProjectVisibleToCaller's workspace-visible branch.
        visibility: "workspace",
        created_by: ownerId,
        portal_enabled: true,
      })
      .select("id")
      .single();
    if (projectErr || !project) throw new Error(`project: ${projectErr?.message}`);
    projectId = project.id;

    // Only projectMemberId (not ownerId) has an explicit project_members
    // row -- proving the owner/admin bypass isProjectVisibleToCaller used
    // to grant is gone too.
    await admin.from("project_members").insert([
      { project_id: projectId, user_id: projectMemberId, project_role: "lead", added_by: ownerId },
      { project_id: projectId, user_id: clientId, project_role: "member", added_by: ownerId },
    ]);

    const signIn = async (email: string) => {
      const session = createClient(SUPABASE_URL!, PUBLISHABLE_KEY!, {
        auth: { autoRefreshToken: false, persistSession: false },
      });
      const { error } = await session.auth.signInWithPassword({ email, password: PASSWORD });
      if (error) throw new Error(`sign in ${email}: ${error.message}`);
      return session;
    };
    ownerSession = await signIn(owner.email);
    projectMemberSession = await signIn(projMember.email);
    clientSession = await signIn(client.email);
    outsiderSession = await signIn(outsider.email);
  }, 60_000);

  afterAll(async () => {
    if (!admin) return;
    if (createdChannelIds.length) {
      await admin.from("channel_members").delete().in("channel_id", createdChannelIds);
      await admin.from("channels").delete().in("id", createdChannelIds);
    }
    if (projectChannelId) {
      await admin.from("channel_members").delete().eq("channel_id", projectChannelId);
      await admin.from("channels").delete().eq("id", projectChannelId);
    }
    await admin.from("project_members").delete().eq("project_id", projectId);
    await admin.from("projects").delete().eq("id", projectId);
    await admin.from("workspace_members").delete().in("workspace_id", [workspaceId, outsiderWorkspaceId]);
    await admin.from("workspaces").delete().in("id", [workspaceId, outsiderWorkspaceId]);
    for (const id of createdUserIds) await admin.auth.admin.deleteUser(id);
  }, 60_000);

  describe("item 2 — create_channel_atomic direct-RPC authorisation (regression, matches this task's own scenario wording)", () => {
    it("an ordinary signed-in user calling create_channel_atomic directly over PostgREST with a fabricated member list is rejected", async () => {
      const { data, error } = await outsiderSession.rpc("create_channel_atomic", {
        p_workspace_id: workspaceId,
        p_kind: "channel",
        p_created_by: outsiderId,
        // Fabricated member list naming real users of the TARGET workspace
        // the caller does not belong to.
        p_member_ids: [outsiderId, ownerId, projectMemberId],
        p_name: "F117 fabricated-membership channel",
      });

      expect(error).not.toBeNull();
      expect(error?.code).toBe(RLS_DENIED);
      expect(data).toBeNull();

      const { data: rows } = await admin
        .from("channels")
        .select("id")
        .eq("workspace_id", workspaceId)
        .eq("name", "F117 fabricated-membership channel");
      expect(rows ?? []).toHaveLength(0);
    });

    it("a client (self-enrollable participant as of F116) cannot self-enroll into an arbitrary channel via a direct create_channel_atomic call", async () => {
      const { data, error } = await clientSession.rpc("create_channel_atomic", {
        p_workspace_id: workspaceId,
        p_kind: "channel",
        p_created_by: clientId,
        p_member_ids: [clientId],
        p_name: "F117 client self-enroll channel",
      });

      expect(error).not.toBeNull();
      expect(error?.code).toBe(RLS_DENIED);
      expect(data).toBeNull();

      const { data: rows } = await admin
        .from("channels")
        .select("id")
        .eq("workspace_id", workspaceId)
        .eq("name", "F117 client self-enroll channel");
      expect(rows ?? []).toHaveLength(0);
    });
  });

  describe("item 3 — createChannel's project-scoped INSERT check now matches the project_members-only browse rule", () => {
    it("an active workspace OWNER who is not an explicit project_members row cannot create the project's channel", async () => {
      const { createChannel } = await import("@/lib/actions/chat-channels");

      currentTestClient = {
        auth: { getUser: async () => ({ data: { user: { id: ownerId } } }) },
      };

      const result = await createChannel({
        workspaceId,
        kind: "channel",
        name: "F117 owner-not-project-member channel",
        projectId,
        memberIds: [],
      });

      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.error).toBe("Project not found.");
      }

      const { data: rows } = await admin
        .from("channels")
        .select("id")
        .eq("project_id", projectId);
      expect(rows ?? []).toHaveLength(0);
    });

    it("an explicit project_members row CAN still create the project's channel", async () => {
      const { createChannel } = await import("@/lib/actions/chat-channels");

      currentTestClient = {
        auth: { getUser: async () => ({ data: { user: { id: projectMemberId } } }) },
      };

      const result = await createChannel({
        workspaceId,
        kind: "channel",
        name: "F117 project member channel",
        projectId,
        memberIds: [clientId],
      });

      expect(result.ok).toBe(true);
      if (result.ok) {
        projectChannelId = result.data.id;

        const { data: memberRows } = await admin
          .from("channel_members")
          .select("user_id")
          .eq("channel_id", result.data.id);
        expect((memberRows ?? []).map((r) => r.user_id).sort()).toEqual(
          [projectMemberId, clientId].sort(),
        );
      }
    });
  });
});

