  // protects against a future regression narrowing that unintentionally.
  it("test_AS_462_guest_sees_create_task_and_create_project_same_as_a_member", async () => {
    mockRole = "guest";
    await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Create task")).toBeInTheDocument();
    });

    expect(screen.getByText("Create project")).toBeInTheDocument();
  });

  it("test_AS_462_typing_a_query_hides_the_actions_group", async () => {
    const input = await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Actions")).toBeInTheDocument();
    });

    fireEvent.change(await input, { target: { value: "abc" } });

    await waitFor(() => {
      expect(screen.queryByText("Actions")).not.toBeInTheDocument();
    });
  });
});

describe("CommandPalette recents (F243, AS-465)", () => {
  it("test_AS_465_recent_items_render_for_an_empty_query_resolved_via_the_server", async () => {
    window.localStorage.setItem(
      "pm-app:palette-recents:ws-1",
      JSON.stringify([{ type: "project", id: "proj-9", visitedAt: Date.now() }]),
    );
    resolveRecentItems.mockResolvedValue({
      projects: [{ type: "project", id: "proj-9", name: "Recently Visited Co", key: "RVC" }],
      tasks: [],
    });

    await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Recent")).toBeInTheDocument();
      expect(screen.getByText("Recently Visited Co")).toBeInTheDocument();
    });

    // AS-465's "resolved server-side" contract: the raw pointer, not a
    // cached name, is what's sent for resolution.
    expect(resolveRecentItems).toHaveBeenCalledWith(
      "ws-1",
      expect.arrayContaining([
        expect.objectContaining({ type: "project", id: "proj-9" }),
      ]),
    );
  });

  it("test_AS_465_typing_a_query_hides_the_recents_group", async () => {
    window.localStorage.setItem(
      "pm-app:palette-recents:ws-1",
      JSON.stringify([{ type: "project", id: "proj-9", visitedAt: Date.now() }]),
    );
    resolveRecentItems.mockResolvedValue({
      projects: [{ type: "project", id: "proj-9", name: "Recently Visited Co", key: "RVC" }],
      tasks: [],
    });

    const input = await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Recent")).toBeInTheDocument();
    });

    fireEvent.change(await input, { target: { value: "xyz" } });

    await waitFor(() => {
      expect(screen.queryByText("Recent")).not.toBeInTheDocument();
    });
  });

  // Negative case (this feature's core correctness requirement): a
  // pointer to a project/task the caller has since lost visibility to
  // (removed from the project, project made private, etc.) must not be
  // shown, and must not confirm the item exists. Since resolution is
  // entirely server-driven (resolveRecentItems), the client-side proof of
  // this is that a pointer resolving to an EMPTY set (exactly what the
  // real Server Action returns once RLS excludes the row -- see
  // tests/integration/palette-recent-items-visibility.test.ts for the
  // live-DB proof) never renders anything for it, and no title/name ever
  // leaks into the DOM.
  it("test_AS_465_stale_or_now_invisible_pointer_renders_nothing_and_leaks_no_title", async () => {
    window.localStorage.setItem(
      "pm-app:palette-recents:ws-1",
      JSON.stringify([{ type: "project", id: "proj-secret", visitedAt: Date.now() }]),
    );
    // The real resolveRecentItems drops any pointer RLS no longer returns
    // a row for -- simulated here as an empty result.
    resolveRecentItems.mockResolvedValue({ projects: [], tasks: [] });

    await openPalette();

    await waitFor(() => {
      expect(resolveRecentItems).toHaveBeenCalled();
    });

    expect(screen.queryByText("Recent")).not.toBeInTheDocument();
    expect(screen.queryByText("proj-secret")).not.toBeInTheDocument();
  });

  it("test_AS_465_no_recents_and_no_actions_falls_back_to_the_neutral_prompt", async () => {
    // Assert the ordinary "no recents yet" case still shows the
    // Recent-less, Actions-only view without a crash, and that the bare
    // neutral prompt only appears when NEITHER actions nor recents
    // exist.
    resolveRecentItems.mockResolvedValue({ projects: [], tasks: [] });

    await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Actions")).toBeInTheDocument();
    });
    expect(screen.queryByText("Recent")).not.toBeInTheDocument();
    expect(
      screen.queryByText("Type to search projects, tasks, and people."),
    ).not.toBeInTheDocument();
  });

  it("test_AS_465_selecting_a_recent_task_navigates_to_its_project_board", async () => {
    window.localStorage.setItem(
      "pm-app:palette-recents:ws-1",
      JSON.stringify([{ type: "task", id: "task-7", visitedAt: Date.now() }]),
    );
    resolveRecentItems.mockResolvedValue({
      projects: [],
      tasks: [
        {
          type: "task",
          id: "task-7",
          title: "Ship the thing",
          projectId: "proj-3",
          projectName: "Launch",
          projectKey: "LNC",
          number: 7,
        },
      ],
    });

    await openPalette();

    await waitFor(() => {
      expect(screen.getByText("Ship the thing")).toBeInTheDocument();
    });

    fireEvent.click(screen.getByText("Ship the thing"));

    await waitFor(() => {
      expect(push).toHaveBeenCalledWith("/w/acme/projects/proj-3/board");
    });
  });
});

// @vitest-environment jsdom
//
// Regression test for a real bug in components/views/view-tabs.tsx's
// `move` handler: the "move right" branch used `tabs[index]` (the tab's
// OWN current position) as the `before` anchor instead of `tabs[swapWith]`
// (the tab it's swapping past). That could compute a new position that
// still sorted BEFORE the tab it was supposed to move past, silently
// failing to reorder instead of throwing -- exactly the kind of bug that
// slips past manual testing (mentioned in the task as "some errors when I
// make a custom view" -- views-as-tabs is part of that same feature area).
//
// This test reverts the fix mentally by checking the ACTUAL position value
// passed to `updateSavedView` on a "move right" click: it must fall
// strictly between the position of the tab being passed (tabs[swapWith])
// and the tab after it (tabs[swapWith + 1]) -- never anchored off the
// moved tab's own old position.

import { describe, expect, it, vi, beforeEach } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";

const updateSavedViewMock = vi.fn(async (_input: { viewId: string; position: number }) => ({
  ok: true as const,
  data: {},
}));

vi.mock("@/lib/actions/views", () => ({
  updateSavedView: (input: { viewId: string; position: number }) => updateSavedViewMock(input),
}));

vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: vi.fn(), refresh: vi.fn() }),
  usePathname: () => "/w/acme/projects/p1/list",
}));

vi.mock("@/components/auth/membership-provider", () => ({
  useMembership: () => ({ role: "admin", hasClient: false, projectRoles: {} }),
}));

import { ViewTabs } from "@/components/views/view-tabs";

describe("ViewTabs reorder (F401 views-as-tabs)", () => {
  beforeEach(() => {
    updateSavedViewMock.mockClear();
  });

  it("test_view_tabs_move_right_anchors_between_the_swapped_tab_and_its_new_next_neighbor", async () => {
    // Three shared tabs at fractional positions -- deliberately unevenly
    // spaced (not simple integers) so the old, buggy `before = tabs[index]`
    // anchor would compute a midpoint that could still sort before
    // `tabs[1]`'s own position, exposing the bug instead of accidentally
    // passing.
    // Deliberately TIGHT spacing between "Design" and "Dev" (105 -> 110):
    // the old buggy anchor (tabs[index]'s own position, 100) averaged with
    // 110 lands exactly ON "Design"'s position (105) -- a real collision,
    // not just "off by a little" -- which is what makes this a reliable
    // regression check rather than a coincidental pass.
    const views = [
      { id: "a", ownerId: "u1", name: "Setup", scope: "shared" as const, viewType: "list" as const, config: { filters: [], sort: [], groupBy: null }, isDefault: false, isMine: true, position: 100 },
      { id: "b", ownerId: "u1", name: "Design", scope: "shared" as const, viewType: "list" as const, config: { filters: [], sort: [], groupBy: null }, isDefault: false, isMine: true, position: 105 },
      { id: "c", ownerId: "u1", name: "Dev", scope: "shared" as const, viewType: "list" as const, config: { filters: [], sort: [], groupBy: null }, isDefault: false, isMine: true, position: 110 },
    ];

    render(<ViewTabs views={views} activeViewId={undefined} />);

    // Move "Setup" (index 0) to the right, past "Design" (index 1).
    const moveRightButton = screen.getByLabelText('Move "Setup" later');
    fireEvent.click(moveRightButton);

    expect(updateSavedViewMock).toHaveBeenCalledTimes(1);
    const call = updateSavedViewMock.mock.calls[0][0];
    expect(call.viewId).toBe("a");
    // Correct anchors: between tabs[1] ("Design", 105) and tabs[2] ("Dev", 110).
    expect(call.position).toBeGreaterThan(105);
    expect(call.position).toBeLessThan(110);
  });
});
